DO $$ DECLARE definition text; BEGIN SELECT pg_get_functiondef('public.journal_window14333(date,date,integer)'::regprocedure) INTO definition; IF position('ORDER BY coalesce(l.line_date,e.transaction_date) DESC,e.id,l.line_no' in definition)=0 THEN RAISE EXCEPTION 'Journal read ordering changed; review before applying';END IF; EXECUTE replace(definition,'ORDER BY coalesce(l.line_date,e.transaction_date) DESC,e.id,l.line_no','ORDER BY e.transaction_date DESC,e.id,l.line_no');END $$;
